\title{A Functorial Tropical Ultrametric on the Boundary of the Berggren Tree}
\author{Aristotle (Harmonic)}
\date{2026-06-16}

\begin{document}

\begin{abstract}
The primitive Pythagorean triples form the vertex set of a rooted ternary tree---the
\emph{Berggren tree}---generated from the seed $(3,4,5)$ by three integer linear maps
that act as discrete Lorentz transformations preserving the form $a^2+b^2-c^2$. We
study the boundary of this tree, the space $\Addr=\NN\to\{0,1,2\}$ of infinite branch
addresses, and equip it with the canonical first-disagreement ultrametric
$d(x,y)=(1/2)^{\fd(x,y)}$. We prove that $(\Addr,d)$ is a genuine ultrametric space,
that each of the three Berggren branch insertions is an \emph{exact} $(1/2)$-similarity
while distinct branches sit at maximal distance $1$, and that the construction has a
tropical (min-plus) core: $\min(\fd(x,y),\fd(y,z))\le \fd(x,z)$ and
$\fd(\cons k\,x,\cons k\,y)=\fd(x,y)+1$. We connect the boundary geometry to triangle
arithmetic via the two-sided depth--hypotenuse law $5\cdot 3^n\le c\le 5\cdot 7^n$ along
the all-$B$ ray, and we build a functorial bridge to a category of tropical-valuation /
ultrametric objects through the Gaussian integers, where the norm $N(m+ni)=m^2+n^2$
recovers the hypotenuse and is multiplicative. All results are formally verified.
\end{abstract}

\maketitle

\section{Introduction}

A \emph{primitive Pythagorean triple} is a triple of positive integers $(a,b,c)$ with
$\gcd(a,b,c)=1$ and $a^2+b^2=c^2$. The classical Barning--Hall parametrization, also
associated with Berggren, organizes all such triples into a rooted ternary tree: the
root is $(3,4,5)$ and each node has exactly three children obtained by applying three
fixed unimodular (up to sign) integer matrices; every primitive triple appears exactly
once.

This paper concerns the tree's \emph{boundary}: the set of infinite root-to-infinity
paths, $\Addr:=\NN\to\{0,1,2\}$. The boundary carries a natural ultrametric of
``first disagreement'' type, and our central observation is that for the Berggren tree
this ultrametric is unusually rigid and arithmetically meaningful:
\begin{enumerate}
  \item the three branch insertions are \emph{exact half-scale similarities}
    (ratio $1/2$), and distinct branches map into disjoint clopen balls at distance $1$;
  \item the construction has a tropical (min-plus) skeleton: agreement depth is
    sub-additive in the min-plus sense, and branch insertion acts on the
    first-disagreement valuation by $n\mapsto n+1$;
  \item the boundary geometry is calibrated to triangle size: along a fixed ray the
    hypotenuse grows geometrically with explicit two-sided constants, so metric depth is
    $\Theta(\log c)$;
  \item the whole picture is functorial through the Gaussian-integer encoding of triples.
\end{enumerate}

\section{The Berggren tree and its boundary}

Work on $\ZZ^3$ with the \emph{Lorentzian quadratic form} $Q(a,b,c)=a^2+b^2-c^2$. A
triple is Pythagorean iff it lies on the light cone $Q=0$. Define three child maps:
\begin{align*}
  \operatorname{childA}(a,b,c) &= (a-2b+2c,\; 2a-b+2c,\; 2a-2b+3c),\\
  \operatorname{childB}(a,b,c) &= (a+2b+2c,\; 2a+b+2c,\; 2a+2b+3c),\\
  \operatorname{childC}(a,b,c) &= (-a+2b+2c,\; -2a+b+2c,\; -2a+2b+3c),
\end{align*}
with associated integer matrices
\[
A=\begin{pmatrix}1&-2&2\\2&-1&2\\2&-2&3\end{pmatrix},\quad
B=\begin{pmatrix}1&2&2\\2&1&2\\2&2&3\end{pmatrix},\quad
C=\begin{pmatrix}-1&2&2\\-2&1&2\\-2&2&3\end{pmatrix}.
\]

\begin{proposition}[Lorentz invariance]
Each generator preserves the Lorentz form, $M^{\mathsf T} Q_L M = Q_L$ with
$Q_L=\operatorname{diag}(1,1,-1)$. Hence each child map preserves $Q$ exactly and maps
Pythagorean triples to Pythagorean triples. The determinants are $\det A=+1$,
$\det B=-1$, $\det C=+1$, giving a $\ZZ/2$-grading by orientation.
\end{proposition}
\begin{proof}[Proof sketch]
Direct matrix computation for the metric identities; $Q(\operatorname{childX})=Q$ is a
polynomial identity verified by expansion; determinants are $3\times3$ computations.
\end{proof}

A node at depth $n$ is reached by a word in $\{A,B,C\}$ of length $n$. An infinite word
is an element of $\Addr:=\NN\to\{0,1,2\}$. The \emph{branch insertion} prepends a letter:
\[
\cons k\,x = \bigl(n\mapsto \text{if } n=0 \text{ then } k \text{ else } x(n-1)\bigr),
\]
so $\cons k\,x\,(0)=k$ and $\cons k\,x\,(m+1)=x(m)$.

\section{The first-disagreement index}

\begin{definition}
For $x,y\in\Addr$, the \emph{first-difference index} $\fd(x,y)$ is the least $n$ with
$x(n)\ne y(n)$ if such an $n$ exists, and $0$ otherwise.
\end{definition}

\begin{lemma}\label{lem:fd}
If $x\ne y$ then $x(\fd(x,y))\ne y(\fd(x,y))$ (witness), and for $m<\fd(x,y)$ we have
$x(m)=y(m)$ (agreement below the index). Moreover $\fd(x,y)=\fd(y,x)$ (symmetry).
\end{lemma}
\begin{proof}[Proof sketch]
The first two are the specification and minimality of the least-witness operator; symmetry
holds because $x(n)\ne y(n)\iff y(n)\ne x(n)$.
\end{proof}

\begin{theorem}[Min-plus core]\label{thm:minplus}
For pairwise-distinct $x,y,z$,
\[
\min\bigl(\fd(x,y),\fd(y,z)\bigr)\le \fd(x,z).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Let $p=\min(\fd(x,y),\fd(y,z))$. For each $i<p$, Lemma~\ref{lem:fd} gives $x(i)=y(i)$ and
$y(i)=z(i)$, hence $x(i)=z(i)$. So $x$ and $z$ agree on all indices below $p$, whence
$\fd(x,z)\ge p$.
\end{proof}

\begin{theorem}[Tropical multiplication law]\label{thm:trop}
For $x\ne y$ and any letter $k$, $\fd(\cons k\,x,\cons k\,y)=\fd(x,y)+1$.
\end{theorem}
\begin{proof}[Proof sketch]
The prepended words agree at index $0$ and, for $m\ge1$, satisfy
$\cons k\,x(m)=x(m-1)$, $\cons k\,y(m)=y(m-1)$; so the first disagreement is shifted one
step later. One checks the least-witness characterization at $\fd(x,y)+1$.
\end{proof}

\section{The tree ultrametric}

\begin{definition}
$d(x,y) = 0$ if $x=y$, and $d(x,y)=(1/2)^{\fd(x,y)}$ otherwise.
\end{definition}

\begin{theorem}\label{thm:axioms}
For all $x,y,z$: $d(x,x)=0$; $0\le d(x,y)$; $d(x,y)=d(y,x)$; $d(x,y)=0\iff x=y$; and
$d(x,y)\le 1$.
\end{theorem}
\begin{proof}[Proof sketch]
Immediate case splits; positivity of $(1/2)^k$ gives the nondegeneracy direction;
symmetry from Lemma~\ref{lem:fd}; $d\le 1$ since $0\le 1/2\le 1$.
\end{proof}

\begin{theorem}[Strong triangle inequality]\label{thm:ultra}
$d(x,z)\le \max\bigl(d(x,y),d(y,z)\bigr)$ for all $x,y,z$.
\end{theorem}
\begin{proof}[Proof sketch]
Degenerate cases are direct. Otherwise, Theorem~\ref{thm:minplus} gives
$\fd(x,z)\ge\min(\fd(x,y),\fd(y,z))$. Since $t\mapsto(1/2)^t$ is antitone, the larger
exponent yields the smaller value, turning a $\min$ of exponents into a $\max$ of
distances; a case split on the realizing index finishes via monotonicity of powers.
\end{proof}

\begin{corollary}
$d(x,z)\le d(x,y)+d(y,z)$; thus $(\Addr,d)$ is a metric space, and an ultrametric one.
\end{corollary}

\section{The branch maps are exact $(1/2)$-similarities}

\begin{theorem}[Half-scale similarity]\label{thm:half}
For every letter $k$ and all $x,y$, $\; d(\cons k\,x,\cons k\,y)=\tfrac12\,d(x,y)$.
\end{theorem}
\begin{proof}[Proof sketch]
If $x=y$ both sides vanish. Otherwise Theorem~\ref{thm:trop} gives exponent
$\fd(x,y)+1$, so $d(\cons k\,x,\cons k\,y)=(1/2)^{\fd(x,y)+1}=\tfrac12\,d(x,y)$.
\end{proof}

\begin{theorem}[Maximal separation]\label{thm:sep}
If $j\ne k$ then $d(\cons j\,x,\cons k\,y)=1$ for all $x,y$.
\end{theorem}
\begin{proof}[Proof sketch]
$\cons j\,x$ and $\cons k\,y$ disagree at index $0$, so $\fd=0$ and $d=1$.
\end{proof}

\begin{remark}
Theorems~\ref{thm:half}--\ref{thm:sep} make $\{\cons 0,\cons 1,\cons 2\}$ an iterated
function system of three $1/2$-similarities satisfying the open-set condition (the three
images are disjoint clopen balls at distance $1$). With $3^n$ depth-$n$ cylinders of
diameter $2^{-n}$, the boundary is a Cantor space of Hausdorff dimension
$\dimH(\Addr,d)=\log 3/\log 2$.
\end{remark}

\section{Calibration to triangle size}

Let $\operatorname{hypB}(a,b,c)=2a+2b+3c$.

\begin{lemma}[Per-step bounds]\label{lem:step}
For a Pythagorean $(a,b,c)$ with $0<a,b\le c$: $\;3c\le \operatorname{hypB}(a,b,c)\le 7c$.
\end{lemma}

\begin{theorem}[Two-sided depth--hypotenuse window]\label{thm:window}
Let $c_n$ be the hypotenuse reached from $(3,4,5)$ by $n$ consecutive $B$-steps. Then
\[
5\cdot 3^n \;\le\; c_n \;\le\; 5\cdot 7^n.
\]
\end{theorem}
\begin{proof}[Proof sketch]
$c_0=5$. Each $B$-step preserves Pythagoreanness, positivity of legs, and (on the cone)
$\text{leg}\le c$, so Lemma~\ref{lem:step} applies at every step; induction gives the
geometric envelope with both constants equal to $5$.
\end{proof}

\begin{corollary}
Reaching hypotenuse $c$ along this ray needs $n=\Theta(\log c)$ steps; the ball of radius
$2^{-n}$ is the depth-$n$ cylinder, so metric resolution and arithmetic scale agree up to
constants.
\end{corollary}

\section{The Gaussian-integer functorial bridge}

Every primitive triple arises from coprime $m>n>0$ of opposite parity as
$(m^2-n^2,\,2mn,\,m^2+n^2)$, the real part, imaginary part, and squared modulus of
$(m+ni)^2\in\Zi$, with $|m+ni|^2=m^2+n^2$.

\begin{lemma}\label{lem:norm}
$N(m+ni):=m^2+n^2=c$, the hypotenuse; and $N(zw)=N(z)\,N(w)$ for $z,w\in\Zi$.
\end{lemma}
\begin{proof}[Proof sketch]
The first is the definition of the encoding; multiplicativity is the field norm of
$\mathbb{Q}(i)/\mathbb{Q}$ restricted to integers, $\Zi$ being a domain.
\end{proof}

We work in a category whose objects are tropical-valuation carriers: a ring-like type
with operations $(+,\cdot,-,0)$ and a valuation $v:R\to\NN$, from which an
\emph{ultrametric-norm object} is produced by an explicit functor
$\operatorname{valuationReconstruct}$; the companion $\operatorname{tropicalization}$
sends ultrametric-norm objects to the standard tropical object on $(\NN,\max,+)$. Both are
functorial (they preserve identities and composition).

\begin{construction}
$\operatorname{gaussianSupportCarrier}$ is the carrier on $\Zi$ with support valuation
$\operatorname{gval}(z)=[z\ne 0]$. Since $\Zi$ is a domain, $\operatorname{gval}$ is
multiplicative (a product vanishes only if a factor does).
\end{construction}

\begin{theorem}[Reconstruction]\label{thm:recon}
Applying $\operatorname{valuationReconstruct}$ to $\operatorname{gaussianSupportCarrier}$
yields an ultrametric-norm object whose induced distance satisfies the strong triangle
inequality; the Gaussian norm $N$ furnishes the multiplicative scale (= hypotenuse), and
the first-disagreement valuation of \S3 is the order-dual min-plus incarnation of the same
datum.
\end{theorem}
\begin{proof}[Proof sketch]
$\operatorname{valuationReconstruct}$ carries any valuation carrier to an ultrametric
object; instantiate at $\operatorname{gaussianSupportCarrier}$. Multiplicativity and the
zero law transport from Lemma~\ref{lem:norm} and the domain property.
\end{proof}

\begin{remark}
The support valuation is the trivial endpoint of a family of Gaussian valuations; the
$(1+i)$-adic valuation is the nontrivial refinement that should read off the $2$-adic
valuation of the even leg $2mn$.
\end{remark}

\section{Discussion and future directions}

\textbf{C1. Completeness and compactness.} $(\Addr,d)$ should be a complete, compact
Cantor space: an address sequence is Cauchy iff every coordinate stabilizes, giving a
unique coordinatewise limit; totally bounded $+$ complete $\Rightarrow$ compact, with
diameter $\le 1$.

\smallskip\noindent\textbf{C2. Hausdorff dimension $=\log 3/\log 2$.} The open-set
condition holds by Theorems~\ref{thm:half}--\ref{thm:sep}; a two-sided Hausdorff-measure
estimate over the $3^n$ cylinders of diameter $2^{-n}$ should pin the dimension.

\smallskip\noindent\textbf{C3. Uniform depth--size law.} Extend Theorem~\ref{thm:window}
to every ray: $\alpha\,\rho_{\min}^n\le c\le \beta\,\rho_{\max}^n$ with $\rho_{\min},
\rho_{\max}$ the extreme per-generator hypotenuse-expansion factors.

\smallskip\noindent\textbf{C4. Categorical Berggren action.} Each $\cons k$ is
$1/2$-Lipschitz and acts on the valuation by tropical multiplication, so the free Berggren
monoid should embed faithfully into the endomorphism monoid of a tropical-ultrametric
object.

\smallskip\noindent\textbf{C5. Nontrivial $(1+i)$-adic valuation.} Replacing
$\operatorname{gval}$ by the $(1+i)$-adic valuation $v$ should give $v(m+ni)=v_2(2mn)$.

\section{Conclusion}

The space of all primitive Pythagorean triples, organized by the Berggren tree, has a
boundary that is a self-similar ultrametric Cantor space governed by a min-plus law, whose
branch maps are exact $(1/2)$-similarities at maximal separation, whose metric depth is
calibrated to $\log c$ by the explicit window $5\cdot 3^n\le c\le 5\cdot 7^n$, and which
embeds functorially via the multiplicative Gaussian norm $N(m+ni)=m^2+n^2$ into a category
of tropical-valuation objects. Elementary triangle arithmetic, the geometry of trees,
min-plus algebra, and Gaussian number theory are four faces of one structure.

