function FIRST_DIFF(x, y, horizon):
    for n = 0 .. horizon-1:
        if x(n) != y(n): return n
    return 0                            # equal within horizon

function ULTRA_DISTANCE(x, y, horizon):
    if x = y: return 0
    return (1/2) ^ FIRST_DIFF(x, y, horizon)

